package net.wtworkshop.gametest;
import java.util.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.GameType;
import net.minecraft.world.inventory.ClickType;
import net.minecraft.resources.ResourceLocation;
import net.neoforged.neoforge.gametest.*;
import net.wtworkshop.*;
import net.wtworkshop.tool.*;
import net.wtworkshop.station.*;
@GameTestHolder("wt_workshop") @PrefixGameTestTemplate(false)
public final class FeedbackTests {
 private static boolean done(net.minecraft.server.level.ServerPlayer p,String id){var a=p.server.getAdvancements().get(ResourceLocation.parse("wt_workshop:workshop/"+id));return a!=null&&p.getAdvancements().getOrStartProgress(a).isDone();}
 @GameTest(template="empty") public static void levelingRewardsAndWear(GameTestHelper h){var p=h.makeMockServerPlayerInLevel();var item=WorkshopTool.create(ToolType.PICKAXE,ToolData.of("iron","wood","string"));item.setDamageValue(50);int before=item.getDamageValue();ToolLeveling.addXp(item,p,1);h.assertTrue(item.getDamageValue()==before,"Ordinary XP changed wear");float ratio=item.getDamageValue()/(float)item.getMaxDamage();ToolLeveling.addXp(item,p,127);h.assertTrue(WorkshopTool.data(item).level()==1&&done(p,"level_1"),"Level-up not tracked");h.assertTrue(Math.abs(item.getDamageValue()/(float)item.getMaxDamage()-ratio)<.01,"Level-up changed wear ratio");
 var gains=ToolLeveling.gains(ToolType.PICKAXE,ToolData.of("iron","wood","string"),ToolData.of("iron","wood","string").withXp(5,0));h.assertTrue(gains.upgrades()==5&&gains.abilities()==1&&Math.abs(gains.statPercent()-10)<.001,"Wrong multi-level reward summary");h.succeed();}
 @GameTest(template="empty") public static void ownedToolsCatchUpButBareItemsDoNot(GameTestHelper h){var p=h.makeMockServerPlayerInLevel();WorkshopMilestones.inspect(p,new ItemStack(Registration.TOOLS.get(ToolType.PICKAXE).get()));h.assertTrue(!done(p,"pickaxe"),"Unassembled item counted");var data=ToolData.of("iron","wood","string").withXp(5,10).withModifierAdded(Modifier.HASTE).withExpansion("copper");WorkshopMilestones.inspect(p,WorkshopTool.create(ToolType.PICKAXE,data));h.assertTrue(done(p,"pickaxe")&&done(p,"assembled")&&done(p,"level_1")&&done(p,"level_5")&&done(p,"haste")&&done(p,"expansion")&&!done(p,"repair")&&!done(p,"level_10"),"Wrong catch-up milestones");h.succeed();}
 @GameTest(template="empty") public static void actualStationRepairAwardsMilestone(GameTestHelper h){var p=h.makeMockServerPlayerInLevel();p.gameMode.changeGameModeForPlayer(GameType.SURVIVAL);var menu=new StationMenu(1,p.getInventory());var tool=WorkshopTool.create(ToolType.PICKAXE,ToolData.of("iron","wood","string"));tool.setDamageValue(40);menu.getSlot(4).set(tool);menu.getSlot(5).set(new ItemStack(Items.IRON_INGOT));menu.clicked(0,0,ClickType.PICKUP,p);h.assertTrue(done(p,"repair")&&!menu.getCarried().isEmpty()&&menu.getSlot(4).getItem().isEmpty(),"Repair result or milestone missing");h.succeed();}
 @GameTest(template="empty") public static void previewShowsExactCostsAndPartialProgress(GameTestHelper h){var tool=WorkshopTool.create(ToolType.PICKAXE,ToolData.of("iron","wood","string"));var inputs=List.of(ItemStack.EMPTY,ItemStack.EMPTY,ItemStack.EMPTY,tool,new ItemStack(Items.REDSTONE,64));var result=StationLogic.compute(inputs,h.getLevel());var lines=StationDetails.lines(inputs,result);h.assertTrue(result.consume()[4]==16&&lines.stream().anyMatch(c->c.getString().contains("16")),"Preview cost wrong");h.assertTrue(WorkshopTool.data(tool).modifiers().isEmpty()&&inputs.get(4).getCount()==64,"Preview consumed inputs");
 var partial=List.of(ItemStack.EMPTY,ItemStack.EMPTY,ItemStack.EMPTY,tool,new ItemStack(Items.REDSTONE,3));var step=StationLogic.compute(partial,h.getLevel());h.assertTrue(WorkshopTool.data(step.result()).progressOf(Modifier.HASTE)==3&&StationDetails.lines(partial,step).size()>=3,"Missing partial-progress detail");h.succeed();}
 @GameTest(template="empty") public static void questChapterReferencesRealItemsAndMilestones(GameTestHelper h){try{var text=java.nio.file.Files.readString(java.nio.file.Path.of("../art-source/workshop-quests.snbt"));var chapter=net.minecraft.nbt.TagParser.parseTag(text);var quests=chapter.getList("quests",10);h.assertTrue(quests.size()==13,"Wrong quest count");for(var q:quests){var quest=(net.minecraft.nbt.CompoundTag)q;for(var task:quest.getList("tasks",10)){var t=(net.minecraft.nbt.CompoundTag)task;if(t.getString("type").equals("advancement"))h.assertTrue(h.getLevel().getServer().getAdvancements().get(ResourceLocation.parse(t.getString("advancement")))!=null,"Missing quest advancement");if(t.getString("type").equals("item"))h.assertTrue(net.minecraft.core.registries.BuiltInRegistries.ITEM.containsKey(ResourceLocation.parse(t.getCompound("item").getString("id"))),"Missing quest item");}}h.succeed();}catch(Exception e){throw new RuntimeException(e);}}
}
